def rule(psa_history, on_off_history, baseline, week):
    """Standard adaptive rule (Bruchovsky-style): stop when PSA falls
    50% below baseline, restart when it returns to baseline."""
    psa = psa_history[-1]
    on = on_off_history[-1] if on_off_history else 1
    if on == 1 and psa < 0.5 * baseline:
        return 0
    if on == 0 and psa >= baseline:
        return 1
    return on

def rule(psa_history, on_off_history, baseline, week):
    """Slope trigger: restart early when PSA rises fast off-drug, so
    resistant growth never gets a long head start."""
    psa = psa_history[-1]
    on = on_off_history[-1] if on_off_history else 1
    if len(psa_history) > 4:
        vel = (psa - psa_history[-5]) / 4
    else:
        vel = 0.0
    if on == 1 and psa < 0.29 * baseline:
        return 0
    if on == 0 and (psa >= 0.68 * baseline or vel > 0.013 * baseline):
        return 1
    return on

